// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 9: Read open tasks": "in1_Step9Readopentasks"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 9: Read open tasks";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"reserve_body": JSON.stringify({ p_recipe: 'R10.1', p_key: 'late:' + out.task }), "exception_body": JSON.stringify({ recipe: 'R10.1', item: out.work_order, reason: out.reason, detail: out.detail, owner: $('Config').first().json.ops_team })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 9: a task open two working days, or a delivery inside three, goes to Tom's team.
const cfg = $('Config').first().json;
const today = new Date().toISOString().slice(0, 10);
function workingDays(a, b) {
  let n = 0, d = new Date(a + 'T00:00:00Z'); const end = new Date(b + 'T00:00:00Z');
  while (d < end) { d = new Date(d.getTime() + 86400000); if (d.getUTCDay() % 6 !== 0) n++; }
  return n;
}
const out = [];
for (const t of $('Step 9: Read open tasks').first().json.items || []) {
  const open = t.created ? workingDays(t.created, today) : 0;
  const soon = t.delivery_date ? workingDays(today, t.delivery_date) <= cfg.near_delivery_working_days : false;
  if (open >= cfg.late_task_working_days) out.push({ json: { task: t.id, work_order: t.work_order, reason: 'task open two working days', detail: `Task ${t.id} open ${open} working days: ${(t.gaps || []).join('; ')}` } });
  else if (soon) out.push({ json: { task: t.id, work_order: t.work_order, reason: 'delivery inside three working days', detail: `Task ${t.id}, delivery ${t.delivery_date}: ${(t.gaps || []).join('; ')}` } });
}
return out;
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
